const API_URL = "http://localhost:12717/api/auth";

// --- Работа с токенами ---
export const getAccessToken = () => localStorage.getItem("accessToken");
export const getRefreshToken = () => localStorage.getItem("refreshToken");

// --- Декодирование JWT с поддержкой Base64URL ---
export const decodeJWT = (token) => {
    try {
        const base64Url = token.split('.')[1];
        if (!base64Url) return null;

        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const padded = base64.padEnd(base64.length + (4 - base64.length % 4) % 4, '=');

        return JSON.parse(atob(padded));
    } catch (error) {
        console.error("Error decoding JWT:", error);
        return null;
    }
};

// --- Сохранение токенов и ролей ---
export const saveTokens = (access, refresh) => {
    localStorage.setItem("accessToken", access);
    localStorage.setItem("refreshToken", refresh);

    const decoded = decodeJWT(access);
    console.log("Decoded Token in saveTokens:", decoded);

    if (decoded) {
        localStorage.setItem("userId", decoded.id);           // добавляем id
        localStorage.setItem("userRoles", JSON.stringify(decoded.roles || []));
        localStorage.setItem("userEmail", decoded.sub);
    }
};

// --- Получение текущего пользователя ---
export const getCurrentUser = () => {
    const token = getAccessToken();
    console.log("Token from localStorage:", token);

    let roles = [];
    let id = null;

    if (token) {
        const decoded = decodeJWT(token);
        console.log("Decoded Token in getCurrentUser:", decoded);
        if (decoded) {
            roles = decoded.roles || [];
            id = decoded.id || null;       // извлекаем id
        }
    }

    return {
        id: id,
        email: localStorage.getItem("userEmail"),
        roles: roles,
    };
};

export const logout = () => {
    localStorage.removeItem("accessToken");
    localStorage.removeItem("refreshToken");
    localStorage.removeItem("userRoles");
    localStorage.removeItem("userEmail");
    localStorage.removeItem("userId");
};


let isRefreshing = false;
let failedQueue = [];

const processQueue = (error, token = null) => {
    failedQueue.forEach(prom => {
        if (error) {
            prom.reject(error);
        } else {
            prom.resolve(token);
        }
    });
    failedQueue = [];
};

// Функция-обертка для fetch с автоматическим обновлением токена
export const authFetch = async (url, options = {}) => {
    let response = await fetch(url, {
        ...options,
        headers: {
            'Authorization': `Bearer ${getAccessToken()}`,
            'Content-Type': 'application/json',
            ...options.headers,
        },
    });

    // Если токен истек (401), пытаемся обновить
    if (response.status === 401) {
        console.log('Access token expired. Attempting refresh...');

        if (isRefreshing) {
            // Если уже идет процесс обновления, добавляем запрос в очередь
            return new Promise((resolve, reject) => {
                failedQueue.push({ resolve, reject });
            }).then(token => {
                return fetch(url, {
                    ...options,
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json',
                        ...options.headers,
                    },
                });
            }).catch(err => {
                return Promise.reject(err);
            });
        }

        isRefreshing = true;

        try {
            // Пытаемся обновить токены
            const userData = await refreshTokens();

            if (!userData) {
                throw new Error('Refresh failed');
            }

            // Успешно обновили токен, обрабатываем очередь
            isRefreshing = false;
            processQueue(null, getAccessToken());

            // Повторяем оригинальный запрос с новым токеном
            response = await fetch(url, {
                ...options,
                headers: {
                    'Authorization': `Bearer ${getAccessToken()}`,
                    'Content-Type': 'application/json',
                    ...options.headers,
                },
            });
        } catch (refreshError) {
            // Не удалось обновить токен - выходим
            isRefreshing = false;
            processQueue(refreshError, null);
            logout();
            window.location.href = '/login';
            return Promise.reject(refreshError);
        }
    }

    return response;
};

// --- Аутентификация ---
export const login = async (email, password) => {
    const res = await fetch(`${API_URL}/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
    });

    if (!res.ok) {
        const text = await res.text();
        throw new Error(text || "Login failed");
    }

    const data = await res.json();
    saveTokens(data.accessToken, data.refreshToken);

    return getCurrentUser();
};

export const register = async (email, password) => {
    const res = await fetch(`${API_URL}/register`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
    });

    if (!res.ok) {
        const error = new Error("Ошибка регистрации");
        error.status = res.status;
        throw error;
    }

    return res.json().catch(() => ({}));
};

export const refreshTokens = async () => {
    const refreshToken = getRefreshToken();
    if (!refreshToken) return null;

    const res = await fetch(`${API_URL}/refresh`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: refreshToken }),
    });

    if (!res.ok) {
        console.error("Не удалось обновить токен", res.status);
        logout(); // если refresh просрочен
        return null;
    }

    const data = await res.json();
    saveTokens(data.accessToken, data.refreshToken); // Токены сохранены, роли обновлены в Local Storage

    return getCurrentUser(); // <- Это возвращает актуальные данные пользователя
};

// --- Управление ролями ---
export const assignRole = async (email, role) => {
    const res = await authFetch(`${API_URL}/assign-role`, {
        method: "POST",
        body: JSON.stringify({ email, role }),
    });

    if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || `Ошибка: ${res.status}`);
    }

    const responseData = await res.json();

    if (responseData.requiresTokenRefresh) {
        console.log("Role self-assignment detected. Refreshing tokens...");
        try {
            const userData = await refreshTokens();
            if (userData) {
                return userData;
            } else {
                throw new Error("Failed to refresh tokens after role assignment");
            }
        } catch (refreshError) {
            console.error("Token refresh failed:", refreshError);
            throw new Error("Role assigned, but failed to update your session. Please log in again.");
        }
    }

    return responseData;
};

// --- Получение всех пользователей ---
export const getUsers = async () => {
    const res = await authFetch(`${API_URL}/users`, {
        method: "GET",
    });

    if (!res.ok) throw new Error("Ошибка получения пользователей");
    return res.json();
};
